+		for _, m := range members {
+			ex, err := p.expandSrc(m, seen)
+			if err != nil {
+				return nil, err
+			}
+			out = append(out, ex...)
+		}
+		return out, nil
+	}
+	if err := p.checkAlias(src); err != nil {
+		return nil, err
+	}
+	return []string{src}, nil
